return ['domain'=>'taxopress-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl-NL','project-id-version'=>'TaxoPress Pro 3.51.0','pot-creation-date'=>'2026-07-22T18:23:43+00:00','po-revision-date'=>'2026-07-22 18:36+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['TaxoPress Pro'=>'TaxoPress Pro','https://wordpress.org/plugins/simple-tags/'=>'https://wordpress.org/plugins/simple-tags/','TaxoPress allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.'=>'TaxoPress stelt je in staat om Tags, Categorieën en al je WordPress taxonomie termen te creëren en beheren.','TaxoPress'=>'TaxoPress','https://taxopress.com'=>'https://taxopress.com','License key'=>'Licentiesleutel','Status'=>'Status','Your license key provides access to updates and support.'=>'Je licentiesleutel biedt toegang tot updates en ondersteuning.','Activate License'=>'Activeer Licentie','Synonyms'=>'Synoniemen','This feature allows you to associate additional words with each term. For example, "website" can have synonyms such as "websites", "web site", and "web pages".'=>'Deze functie stelt je in staat om extra woorden aan elke term te koppelen. Bijvoorbeeld, "website" kan synoniemen hebben zoals "websites", "web site" en "webpagina\'s".','Linked Terms'=>'Gekoppelde Termen','This feature allows you to connect terms. When the main term or any of these terms are added to the post, all the other terms will be added also.'=>'Deze functie stelt je in staat om termen te verbinden. Wanneer de hoofdterm of een van deze termen aan het bericht wordt toegevoegd, worden ook alle andere termen toegevoegd.','Shortcode Name'=>'Shortcode Naam','Add'=>'Toevoegen','Enter the shortcode name without [ ] or parameters.'=>'Voer de shortcode naam in zonder [ ] of parameters.','Search Block'=>'Zoek Blok','Search...'=>'Zoeken...','Search and select blocks.'=>'Zoek en selecteer blokken.','Element tag'=>'Element tag','Add Element'=>'Element toevoegen','New Element'=>'Nieuw element',